45	    /// Checks that a path specified as parameters of Disk() is valid.
46	    void checkPath(const String & disk_name, const DiskPtr & disk, fs::path & path)
47	    {
48	        path = path.lexically_normal();
49	        if (!path.is_relative() && (disk->getType() == DiskType::Local))
50	            path = path.lexically_proximate(disk->getPath());
51	
52	        bool path_ok = path.empty() || (path.is_relative() && (*path.begin() != ".."));
53	        if (!path_ok)
54	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Path {} to backup must be inside the specified disk {}", quoteString(path.c_str()), quoteString(disk_name));
55	    }
56	
57	    /// Checks that a path specified as parameters of File() is valid.
58	    void checkPath(fs::path & path, const Poco::Util::AbstractConfiguration & config, const fs::path & data_dir)
59	    {
60	        path = path.lexically_normal();
61	        if (path.empty())
62	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Path to backup must not be empty");
63	
64	        String key = "backups.allowed_path";
65	        if (!config.has(key))
66	            throw Exception(ErrorCodes::INVALID_CONFIG_PARAMETER,
67	                            "The 'backups.allowed_path' configuration parameter is not set, cannot use 'File' backup engine");
68	
69	        if (path.is_relative())
70	        {
71	            auto first_allowed_path = fs::path(config.getString(key));
72	            if (first_allowed_path.is_relative())
73	                first_allowed_path = data_dir / first_allowed_path;
74	
75	            path = first_allowed_path / path;
76	        }
77	
78	        size_t counter = 0;
79	        while (true)
80	        {
81	            auto allowed_path = fs::path(config.getString(key));
82	            if (allowed_path.is_relative())
83	                allowed_path = data_dir / allowed_path;
84	            auto rel = path.lexically_proximate(allowed_path);
85	            bool path_ok = rel.empty() || (rel.is_relative() && (*rel.begin() != ".."));
86	            if (path_ok)
87	                break;
88	            key = "backups.allowed_path[" + std::to_string(++counter) + "]";
89	            if (!config.has(key))
90	                throw Exception(ErrorCodes::BAD_ARGUMENTS,
91	                                "Path {} is not allowed for backups, see the 'backups.allowed_path' configuration parameter",
92	                                quoteString(path.c_str()));
93	        }
94	    }
