98	void registerBackupEnginesFileAndDisk(BackupFactory & factory)
99	{
100	    auto creator_fn = [](const BackupFactory::CreateParams & params) -> std::unique_ptr<IBackup>
101	    {
102	        String backup_name = params.backup_info.toString();
103	        const String & engine_name = params.backup_info.backup_engine_name;
104	
105	        if (!params.backup_info.id_arg.empty())
106	        {
107	            throw Exception(
108	                ErrorCodes::BAD_ARGUMENTS,
109	                "Backup engine '{}' requires its first argument to be a string",
110	                engine_name);
111	        }
112	
113	        const auto & args = params.backup_info.args;
114	
115	        DiskPtr disk;
116	        fs::path path;
117	        if (engine_name == "File")
118	        {
119	            if (args.size() != 1)
120	            {
121	                throw Exception(
122	                    "Backup engine 'File' requires 1 argument (path)",
123	                    ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
124	            }
125	
126	            path = args[0].safeGet<String>();
127	            const auto & config = params.context->getConfigRef();
128	            const auto & data_dir = params.context->getPath();
129	            checkPath(path, config, data_dir);
130	        }
131	        else if (engine_name == "Disk")
132	        {
133	            if (args.size() != 2)
134	            {
135	                throw Exception(
136	                    "Backup engine 'Disk' requires 2 arguments (disk_name, path)",
137	                    ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
138	            }
139	
140	            String disk_name = args[0].safeGet<String>();
141	            const auto & config = params.context->getConfigRef();
142	            checkDiskName(disk_name, config);
143	            path = args[1].safeGet<String>();
144	            disk = params.context->getDisk(disk_name);
145	            checkPath(disk_name, disk, path);
146	        }
147	        else
148	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Unexpected backup engine '{}'", engine_name);
149	
150	        BackupImpl::ArchiveParams archive_params;
151	        if (hasRegisteredArchiveFileExtension(path))
152	        {
153	            if (params.is_internal_backup)
154	                throw Exception(ErrorCodes::SUPPORT_IS_DISABLED, "Using archives with backups on clusters is disabled");
155	
156	            archive_params.archive_name = path.filename();
157	            path = path.parent_path();
158	            archive_params.compression_method = params.compression_method;
159	            archive_params.compression_level = params.compression_level;
160	            archive_params.password = params.password;
161	        }
162	        else
163	        {
164	            if (!params.password.empty())
165	                throw Exception(ErrorCodes::BAD_ARGUMENTS, "Password is not applicable, backup cannot be encrypted");
166	        }
167	
168	        if (params.open_mode == IBackup::OpenMode::READ)
169	        {
170	            std::shared_ptr<IBackupReader> reader;
171	            if (engine_name == "File")
172	                reader = std::make_shared<BackupReaderFile>(path);
173	            else
174	                reader = std::make_shared<BackupReaderDisk>(disk, path);
175	            return std::make_unique<BackupImpl>(backup_name, archive_params, params.base_backup_info, reader, params.context);
176	        }
177	        else
178	        {
179	            std::shared_ptr<IBackupWriter> writer;
180	            if (engine_name == "File")
181	                writer = std::make_shared<BackupWriterFile>(path);
182	            else
183	                writer = std::make_shared<BackupWriterDisk>(disk, path);
184	            return std::make_unique<BackupImpl>(backup_name, archive_params, params.base_backup_info, writer, params.context, params.is_internal_backup, params.backup_coordination, params.backup_uuid);
185	        }
186	    };
187	
188	    factory.registerBackupEngine("File", creator_fn);
189	    factory.registerBackupEngine("Disk", creator_fn);
190	}
