33	ASTPtr BackupInfo::toAST() const
34	{
35	    auto func = std::make_shared<ASTFunction>();
36	    func->name = backup_engine_name;
37	    func->no_empty_args = true;
38	
39	    auto list = std::make_shared<ASTExpressionList>();
40	    func->arguments = list;
41	    func->children.push_back(list);
42	    list->children.reserve(args.size() + !id_arg.empty());
43	
44	    if (!id_arg.empty())
45	        list->children.push_back(std::make_shared<ASTIdentifier>(id_arg));
46	
47	    for (const auto & arg : args)
48	        list->children.push_back(std::make_shared<ASTLiteral>(arg));
49	
