54	BackupInfo BackupInfo::fromAST(const IAST & ast)
55	{
56	    const auto * func = ast.as<const ASTFunction>();
57	    if (!func)
58	        throw Exception(ErrorCodes::BAD_ARGUMENTS, "Expected function, got {}", serializeAST(ast));
59	
60	    BackupInfo res;
61	    res.backup_engine_name = func->name;
62	
63	    if (func->arguments)
64	    {
65	        const auto * list = func->arguments->as<const ASTExpressionList>();
66	        if (!list)
67	            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Expected list, got {}", serializeAST(*func->arguments));
68	
69	        size_t index = 0;
70	        if (!list->children.empty())
71	        {
72	            const auto * id = list->children[0]->as<const ASTIdentifier>();
73	            if (id)
74	            {
75	                res.id_arg = id->name();
76	                ++index;
77	            }
78	        }
79	
80	        res.args.reserve(list->children.size() - index);
81	        for (; index < list->children.size(); ++index)
82	        {
83	            const auto & elem = list->children[index];
84	            const auto * lit = elem->as<const ASTLiteral>();
85	            if (!lit)
86	                throw Exception(ErrorCodes::BAD_ARGUMENTS, "Expected literal, got {}", serializeAST(*elem));
87	            res.args.push_back(lit->value);
88	        }
89	    }
90	
91	    return res;
92	}
